type Task = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Timing = { start: number; finish: number };

function fail(message: string): never {
  console.error(`Error: ${message}`);
  process.exit(1);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function parseTasks(value: unknown): Task[] {
  if (!isRecord(value) || !Array.isArray(value.tasks)) fail("input must be an object with a tasks array");
  const rawTasks = value.tasks;
  const ids = new Set<string>();
  const tasks: Task[] = [];

  for (let index = 0; index < rawTasks.length; index++) {
    const raw = rawTasks[index];
    if (!isRecord(raw)) fail(`tasks[${index}] must be an object`);
    const id = raw.id;
    if (typeof id !== "string" || id.length === 0) fail(`tasks[${index}].id must be a non-empty string`);
    if (ids.has(id)) fail(`duplicate task id: ${id}`);
    ids.add(id);
    const duration = raw.duration;
    if (typeof duration !== "number" || !Number.isFinite(duration) || duration < 0) {
      fail(`tasks[${index}].duration must be a finite non-negative number`);
    }
    const dependencies = raw.dependsOn === undefined ? [] : raw.dependsOn;
    if (!Array.isArray(dependencies) || dependencies.some((dep) => typeof dep !== "string")) {
      fail(`tasks[${index}].dependsOn must be an array of strings`);
    }
    const depSet = new Set(dependencies as string[]);
    if (depSet.size !== dependencies.length) fail(`tasks[${index}].dependsOn contains duplicates`);
    if (depSet.has(id)) fail(`task ${id} cannot depend on itself`);
    tasks.push({ id, duration, dependsOn: [...depSet] });
  }

  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) fail(`task ${task.id} depends on unknown task: ${dependency}`);
    }
  }
  return tasks;
}

function findCycle(tasks: Task[], outgoing: Map<string, string[]>): string[] | undefined {
  const state = new Map<string, number>();
  const stack: string[] = [];
  const position = new Map<string, number>();
  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    position.set(id, stack.length);
    stack.push(id);
    for (const next of outgoing.get(id) ?? []) {
      if (state.get(next) === 1) return [...stack.slice(position.get(next)!), next];
      if (!state.has(next)) {
        const cycle = visit(next);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    position.delete(id);
    state.set(id, 2);
    return undefined;
  };
  for (const task of [...tasks].sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0)) {
    if (!state.has(task.id)) {
      const cycle = visit(task.id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

function plan(tasks: Task[]) {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const outgoing = new Map<string, string[]>();
  const indegree = new Map<string, number>();
  for (const task of tasks) {
    outgoing.set(task.id, []);
    indegree.set(task.id, task.dependsOn.length);
  }
  for (const task of tasks) for (const dependency of task.dependsOn) outgoing.get(dependency)!.push(task.id);
  for (const list of outgoing.values()) list.sort((a, b) => a.localeCompare(b));
  const cycle = findCycle(tasks, outgoing);
  if (cycle) fail(`dependency cycle: ${cycle.join(" -> ")}`);

  const ready = [...tasks].filter((task) => indegree.get(task.id) === 0).map((task) => task.id);
  const order: string[] = [];
  const sortIds = (ids: string[]) => ids.sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
  sortIds(ready);
  while (ready.length) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of outgoing.get(id)!) {
      const next = indegree.get(child)! - 1;
      indegree.set(child, next);
      if (next === 0) ready.push(child);
    }
    sortIds(ready);
  }

  const earliest = {} as Record<string, Timing>;
  const layerById = new Map<string, number>();
  for (const id of order) {
    const task = byId.get(id)!;
    const start = task.dependsOn.reduce((max, dep) => Math.max(max, earliest[dep].finish), 0);
    earliest[id] = { start, finish: start + task.duration };
    layerById.set(id, task.dependsOn.reduce((max, dep) => Math.max(max, layerById.get(dep)! + 1), 0));
  }
  const layers: string[][] = [];
  for (const id of order) {
    const layer = layerById.get(id)!;
    (layers[layer] ??= []).push(id);
  }
  layers.forEach(sortIds);
  const totalDuration = Math.max(0, ...Object.values(earliest).map((time) => time.finish));
  const ends = tasks.filter((task) => earliest[task.id].finish === totalDuration).map((task) => task.id);
  let best: string[] = [];
  const compare = (a: string[], b: string[]) => {
    for (let i = 0; i < Math.min(a.length, b.length); i++) {
      const result = a[i] < b[i] ? -1 : a[i] > b[i] ? 1 : 0;
      if (result) return result;
    }
    return a.length - b.length;
  };
  const pathTo = (id: string): string[] => {
    const task = byId.get(id)!;
    if (!task.dependsOn.length) return [id];
    let candidate: string[] = [];
    for (const dep of task.dependsOn) {
      if (earliest[dep].finish === earliest[id].start) {
        const path = [...pathTo(dep), id];
        if (!candidate.length || compare(path, candidate) < 0) candidate = path;
      }
    }
    return candidate.length ? candidate : [id];
  };
  for (const id of sortIds(ends)) {
    const candidate = pathTo(id);
    if (!best.length || compare(candidate, best) < 0) best = candidate;
  }
  return { order, layers, earliest, totalDuration, criticalPath: best };
}

function main() {
  const args = process.argv.slice(2);
  if (args.length !== 2 || args[0] !== "plan") fail("usage: bun run src/cli.ts plan INPUT.json");
  let parsed: unknown;
  try {
    parsed = JSON.parse(require("fs").readFileSync(args[1], "utf8"));
  } catch (error) {
    fail(`cannot read or parse input: ${error instanceof Error ? error.message : String(error)}`);
  }
