bun build src/cli.ts --target bun --outdir /tmp/dependency-planner-build >/tmp/dependency-planner-build.log
bun -e '
import { spawnSync } from "node:child_process";
function run(input: string, args = ["plan", "/dev/stdin"]) {
  return spawnSync("bun", ["run", "src/cli.ts", ...args], { input, encoding: "utf8" });
}
const graph = JSON.stringify({tasks:[
  {id:"z",duration:1},
  {id:"a",duration:0},
  {id:"c",duration:2,dependsOn:["a"]},
  {id:"b",duration:3,dependsOn:["a"]},
  {id:"d",duration:1,dependsOn:["b","c"]}
]});
const planned = run(graph);
if (planned.status !== 0) throw new Error(planned.stderr);
const result = JSON.parse(planned.stdout);
const expected = {
  order:["a","b","c","d","z"],
  layers:[["a","z"],["b","c"],["d"]],
  earliest:{a:{start:0,finish:0},b:{start:0,finish:3},c:{start:0,finish:2},d:{start:3,finish:4},z:{start:0,finish:1}},
  totalDuration:4,
  criticalPath:["a","b","d"]
};
if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error(`unexpected output: ${planned.stdout}`);
for (const bad of [
  JSON.stringify({}),
  JSON.stringify({tasks:[{id:"a",duration:-1}]}),
  JSON.stringify({tasks:[{id:"a",duration:1,dependsOn:["x"]}]}),
  JSON.stringify({tasks:[{id:"a",duration:1},{id:"a",duration:2}]})
]) {
  const failure = run(bad);
  if (failure.status === 0 || !failure.stderr.includes("Error:")) throw new Error("validation did not fail");
}
const cycle = run(JSON.stringify({tasks:[{id:"b",duration:1,dependsOn:["a"]},{id:"a",duration:1,dependsOn:["b"]}]}));
if (cycle.status === 0 || !cycle.stderr.includes("a -> b -> a")) throw new Error(`bad cycle: ${cycle.stderr}`);
const empty = run(JSON.stringify({tasks:[]}));
if (empty.status !== 0 || JSON.parse(empty.stdout).totalDuration !== 0) throw new Error("empty case failed");
console.log("self-tests passed");
'
printf '%s\n' '--- build ---'
sed -n '1,8p' /tmp/dependency-planner-build.log
printf '%s\n' '--- status ---'
git status --short

